style.css:
@-moz-document domain("roblox.com") {
html, body {
    background: url("https://i.imgur.com/kd9fB36.jpeg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Hace transparentes todas las cajas negras más comunes */
  .content, .container-main, .container-header, 
  .rbx-header, .rbx-navbar, .section-content, 
  .footer, .navbar, .container-footer, 
  .game-detail-page, .games-list-container, 
  .home-container, .dark-theme {
    background: transparent !important;
    background-color: transparent !important;
  }

  /* También fuerza el fondo transparente en otras partes */
  div, section, header, footer, main {
    background-color: transparent !important;
    background-image: none !important;
  }

  /* Opcional: cambia el color del texto a blanco para que se vea */
  body, span, div, p, a, h1, h2, h3, h4, h5, h6 {
    color: white !important;
  }
}
